import{_ as r,c as e,o as a,ag as i}from"./chunks/framework.CMajxlqO.js";const h=JSON.parse('{"title":"Frekvensomriktare via Profinet","description":"","frontmatter":{},"headers":[],"relativePath":"03-konfiguration/frekvensomriktare-profinet.md","filePath":"03-konfiguration/frekvensomriktare-profinet.md","lastUpdated":1768315788000}'),n={name:"03-konfiguration/frekvensomriktare-profinet.md"};function l(o,t,s,d,g,m){return a(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="frekvensomriktare-via-profinet" tabindex="-1">Frekvensomriktare via Profinet <a class="header-anchor" href="#frekvensomriktare-via-profinet" aria-label="Permalink to &quot;Frekvensomriktare via Profinet&quot;">​</a></h1><p>Att styra en frekvensomriktare (VFD - Variable Frequency Drive) via Profinet ger dig fullständig kontroll över motorhastighet, riktning och övervakningsparametrar direkt från PLC-programmet. Här lär du dig konfigurera en Sinamics frekvensomriktare i TIA Portal.</p><h2 id="forutsattningar" tabindex="-1">Förutsättningar <a class="header-anchor" href="#forutsattningar" aria-label="Permalink to &quot;Förutsättningar&quot;">​</a></h2><p>Innan du börjar, se till att du har:</p><ul><li>✅ PLC (S7-1200/1500) konfigurerad med Profinet</li><li>✅ Sinamics frekvensomriktare (t.ex. G120, G120C, V20)</li><li>✅ GSD-fil för din frekvensomriktare</li><li>✅ Ethernet-kablar för Profinet-anslutning</li></ul><h2 id="steg-1-installera-gsd-fil" tabindex="-1">Steg 1: Installera GSD-fil <a class="header-anchor" href="#steg-1-installera-gsd-fil" aria-label="Permalink to &quot;Steg 1: Installera GSD-fil&quot;">​</a></h2><p>GSD (General Station Description) är en enhetsbeskrivning som TIA Portal behöver för att känna igen frekvensomriktaren.</p><h3 id="ladda-ner-gsd-fil" tabindex="-1">Ladda ner GSD-fil <a class="header-anchor" href="#ladda-ner-gsd-fil" aria-label="Permalink to &quot;Ladda ner GSD-fil&quot;">​</a></h3><ol><li>Gå till <a href="https://support.industry.siemens.com" target="_blank" rel="noreferrer">Siemens Support Portal</a></li><li>Sök efter din frekvensomriktare (t.ex. &quot;Sinamics G120 GSD&quot;)</li><li>Ladda ner senaste GSDML-filen (XML-format)</li><li>Spara filen på din dator</li></ol><h3 id="installera-gsd-i-tia-portal" tabindex="-1">Installera GSD i TIA Portal <a class="header-anchor" href="#installera-gsd-i-tia-portal" aria-label="Permalink to &quot;Installera GSD i TIA Portal&quot;">​</a></h3><ol><li>I TIA Portal: <strong>Options</strong> → <strong>Install general station description file (GSD)</strong></li><li>Klicka <strong>Browse</strong> och välj nedladdad GSD-fil</li><li>Klicka <strong>Install</strong></li><li>Vänta på installation (kan ta 1-2 minuter)</li><li>Bekräfta att installation lyckades</li><li>Starta om TIA Portal för att aktivera GSD-filen</li></ol><div class="tip custom-block"><p class="custom-block-title">Tips</p><p>GSD-filer är kompatibla mellan många Siemens-produkter. En GSD för G120 fungerar ofta för flera G120-varianter.</p></div><h2 id="steg-2-lagg-till-frekvensomriktare-i-projektet" tabindex="-1">Steg 2: Lägg till frekvensomriktare i projektet <a class="header-anchor" href="#steg-2-lagg-till-frekvensomriktare-i-projektet" aria-label="Permalink to &quot;Steg 2: Lägg till frekvensomriktare i projektet&quot;">​</a></h2><h3 id="hitta-i-hardvarukatalogen" tabindex="-1">Hitta i hårdvarukatalogen <a class="header-anchor" href="#hitta-i-hardvarukatalogen" aria-label="Permalink to &quot;Hitta i hårdvarukatalogen&quot;">​</a></h3><ol><li>Öppna <strong>Devices &amp; Networks</strong></li><li>Öppna hårdvarukatalogen (höger sida)</li><li>Navigera till: <ul><li><strong>Other field devices</strong></li><li><strong>PROFINET IO</strong></li><li><strong>Drives</strong></li><li><strong>Siemens AG</strong></li><li><strong>SINAMICS</strong></li></ul></li><li>Välj din modell (t.ex. &quot;SINAMICS G120 CU250S-2 PN&quot;)</li></ol><h3 id="dra-till-natverksvyn" tabindex="-1">Dra till nätverksvyn <a class="header-anchor" href="#dra-till-natverksvyn" aria-label="Permalink to &quot;Dra till nätverksvyn&quot;">​</a></h3><ol><li>Dra frekvensomriktaren till Network View</li><li>Placera den nära PLC:n visuellt</li><li>Enheten visas som en grå/gul box</li></ol><h2 id="steg-3-anslut-till-profinet-natverket" tabindex="-1">Steg 3: Anslut till Profinet-nätverket <a class="header-anchor" href="#steg-3-anslut-till-profinet-natverket" aria-label="Permalink to &quot;Steg 3: Anslut till Profinet-nätverket&quot;">​</a></h2><h3 id="skapa-profinet-io-system" tabindex="-1">Skapa Profinet IO-system <a class="header-anchor" href="#skapa-profinet-io-system" aria-label="Permalink to &quot;Skapa Profinet IO-system&quot;">​</a></h3><ol><li>Dra en linje från frekvensomriktarens <strong>PN-port</strong> till PLC:ns <strong>PROFINET-interface</strong></li><li>En grön linje skapas = anslutningen är aktiv</li><li>Frekvensomriktaren blir nu en <strong>IO-Device</strong> under PLC:n (IO-Controller)</li></ol><h3 id="konfigurera-enhetsnummer" tabindex="-1">Konfigurera enhetsnummer <a class="header-anchor" href="#konfigurera-enhetsnummer" aria-label="Permalink to &quot;Konfigurera enhetsnummer&quot;">​</a></h3><ol><li>Markera frekvensomriktaren i Network View</li><li>Under <strong>Properties</strong> → <strong>General</strong></li><li><strong>Device number:</strong> Ange ett unikt nummer (t.ex. <code>10</code>) <ul><li>Varje Profinet-enhet måste ha unikt device number</li><li>Använd logisk numrering: 10-19 för drives, 20-29 för I/O, etc.</li></ul></li></ol><h3 id="konfigurera-ip-adress" tabindex="-1">Konfigurera IP-adress <a class="header-anchor" href="#konfigurera-ip-adress" aria-label="Permalink to &quot;Konfigurera IP-adress&quot;">​</a></h3><ol><li>Under <strong>Properties</strong> → <strong>Ethernet addresses</strong></li><li><strong>IP address:</strong> <code>192.168.0.30</code> (samma subnet som PLC)</li><li><strong>Subnet mask:</strong> <code>255.255.255.0</code></li><li><strong>Device name:</strong> <code>g120-drive01</code> (valfritt men rekommenderat)</li></ol><div class="warning custom-block"><p class="custom-block-title">Viktigt</p><p>Kontrollera att IP-adressen inte krockar med andra enheter! PLC och HMI måste ha unika IP:er i samma subnet.</p></div><h2 id="steg-4-konfigurera-telegram-styrord-och-processdata" tabindex="-1">Steg 4: Konfigurera telegram (styrord och processdata) <a class="header-anchor" href="#steg-4-konfigurera-telegram-styrord-och-processdata" aria-label="Permalink to &quot;Steg 4: Konfigurera telegram (styrord och processdata)&quot;">​</a></h2><p>Telegram definierar vilken data som utbyts mellan PLC och omriktare.</p><h3 id="valj-telegramtyp" tabindex="-1">Välj telegramtyp <a class="header-anchor" href="#valj-telegramtyp" aria-label="Permalink to &quot;Välj telegramtyp&quot;">​</a></h3><ol><li>Markera frekvensomriktaren i Device Configuration</li><li>I katalogen (höger sida), expandera enhetens <strong>Modules</strong></li><li>Välj lämpligt telegram och dra till frekvensomriktarens <strong>slot</strong>:</li></ol><h4 id="standard-telegrams-vanligaste" tabindex="-1">Standard telegrams (vanligaste) <a class="header-anchor" href="#standard-telegrams-vanligaste" aria-label="Permalink to &quot;Standard telegrams (vanligaste)&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Telegram</th><th>Beskrivning</th><th>Användning</th></tr></thead><tbody><tr><td><strong>Telegram 1</strong></td><td>Grundläggande styrning</td><td>Start/stopp, hastighet</td></tr><tr><td><strong>Telegram 3</strong></td><td>Utökad med PZD</td><td>Styrning + extra parametrar</td></tr><tr><td><strong>Telegram 20</strong></td><td>PROFIDRIVE</td><td>Avancerad motion control</td></tr><tr><td><strong>Telegram 111</strong></td><td>Standard Speed Control</td><td>Rekommenderas för nybörjare</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Rekommendation</p><p>Börja med <strong>Telegram 1</strong> eller <strong>Telegram 111</strong> för grundläggande hastighetsreglering.</p></div><h3 id="forstaelse-av-telegram-struktur" tabindex="-1">Förståelse av telegram-struktur <a class="header-anchor" href="#forstaelse-av-telegram-struktur" aria-label="Permalink to &quot;Förståelse av telegram-struktur&quot;">​</a></h3><p>Ett telegram består av:</p><ul><li><strong>STW (Steuerwort / Control Word)</strong> - Styrord från PLC till omriktare</li><li><strong>ZSW (Zustandswort / Status Word)</strong> - Statusord från omriktare till PLC</li><li><strong>NSOLL (Speed Setpoint)</strong> - Önskad hastighet från PLC</li><li><strong>NIST (Actual Speed)</strong> - Verklig hastighet från omriktare</li><li><strong>PZD (Process Data)</strong> - Ytterligare parametrar</li></ul><h3 id="tilldela-i-o-adresser" tabindex="-1">Tilldela I/O-adresser <a class="header-anchor" href="#tilldela-i-o-adresser" aria-label="Permalink to &quot;Tilldela I/O-adresser&quot;">​</a></h3><ol><li>Efter att du valt telegram visas <strong>Input</strong> och <strong>Output</strong> områden</li><li>TIA Portal tilldelar automatiskt adresser: <ul><li><strong>Output (från PLC):</strong> t.ex. <code>%QW100</code> (Control Word), <code>%QW102</code> (Setpoint)</li><li><strong>Input (till PLC):</strong> t.ex. <code>%IW100</code> (Status Word), <code>%IW102</code> (Actual Speed)</li></ul></li><li>Notera dessa adresser - du behöver dem i programmeringen!</li></ol><h2 id="steg-5-konfigurera-frekvensomriktaren" tabindex="-1">Steg 5: Konfigurera frekvensomriktaren <a class="header-anchor" href="#steg-5-konfigurera-frekvensomriktaren" aria-label="Permalink to &quot;Steg 5: Konfigurera frekvensomriktaren&quot;">​</a></h2><h3 id="online-konfiguration" tabindex="-1">Online-konfiguration <a class="header-anchor" href="#online-konfiguration" aria-label="Permalink to &quot;Online-konfiguration&quot;">​</a></h3><p>Efter att hårdvaran är konfigurerad i TIA Portal måste du konfigurera frekvensomriktaren själv.</p><h4 id="via-starter-startdrive" tabindex="-1">Via Starter / Startdrive <a class="header-anchor" href="#via-starter-startdrive" aria-label="Permalink to &quot;Via Starter / Startdrive&quot;">​</a></h4><ol><li>Öppna <strong>SINAMICS Startdrive</strong> (integrerat i TIA Portal)</li><li>Eller använd standalone <strong>Starter</strong>-verktyget</li><li>Anslut online till omriktaren</li><li>Kör <strong>Quick Commissioning Wizard</strong>: <ul><li>Motor-parametrar (effekt, ström, spänning)</li><li>Ramp-tider (acceleration/deceleration)</li><li>Gräns hastigheter (min/max)</li><li>Kommunikationsinställningar</li></ul></li></ol><h4 id="grundparametrar-att-satta" tabindex="-1">Grundparametrar att sätta <a class="header-anchor" href="#grundparametrar-att-satta" aria-label="Permalink to &quot;Grundparametrar att sätta&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Parameter</th><th>Beskrivning</th><th>Exempel</th></tr></thead><tbody><tr><td><strong>P0010</strong></td><td>Commissioning mode</td><td><code>1</code> = Quick commissioning</td></tr><tr><td><strong>P0304</strong></td><td>Rated motor voltage</td><td><code>400V</code></td></tr><tr><td><strong>P0305</strong></td><td>Rated motor current</td><td><code>5A</code></td></tr><tr><td><strong>P0307</strong></td><td>Rated motor power</td><td><code>2.2 kW</code></td></tr><tr><td><strong>P1080</strong></td><td>Min frequency</td><td><code>0 Hz</code></td></tr><tr><td><strong>P1082</strong></td><td>Max frequency</td><td><code>50 Hz</code></td></tr><tr><td><strong>P1120</strong></td><td>Ramp-up time</td><td><code>5 s</code></td></tr><tr><td><strong>P1121</strong></td><td>Ramp-down time</td><td><code>5 s</code></td></tr><tr><td><strong>P2009</strong></td><td>Profinet device number</td><td><code>10</code> (samma som i TIA)</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">OBS</p><p>Motorparametrarna måste matcha din motor! Felaktiga parametrar kan skada motor eller omriktare.</p></div><h2 id="steg-6-tilldela-device-name-via-tia-portal" tabindex="-1">Steg 6: Tilldela device name via TIA Portal <a class="header-anchor" href="#steg-6-tilldela-device-name-via-tia-portal" aria-label="Permalink to &quot;Steg 6: Tilldela device name via TIA Portal&quot;">​</a></h2><p>Profinet-enheter identifieras via device name (inte bara IP).</p><h3 id="online-tilldelning" tabindex="-1">Online-tilldelning <a class="header-anchor" href="#online-tilldelning" aria-label="Permalink to &quot;Online-tilldelning&quot;">​</a></h3><ol><li>I TIA Portal: <strong>Online</strong> → <strong>Assign device name</strong></li><li>TIA Portal söker efter åtkomliga enheter</li><li>Välj din frekvensomriktare (visas med MAC-adress)</li><li>Klicka <strong>Assign name</strong></li><li>Enheten får nu det device name du angav i konfigurationen</li></ol><h3 id="alternativ-via-webbgranssnitt" tabindex="-1">Alternativ: Via webbgränssnitt <a class="header-anchor" href="#alternativ-via-webbgranssnitt" aria-label="Permalink to &quot;Alternativ: Via webbgränssnitt&quot;">​</a></h3><p>Många Sinamics har inbyggd webbserver:</p><ol><li>Öppna webbläsare</li><li>Gå till omriktarens IP (t.ex. <code>http://192.168.0.30</code>)</li><li>Logga in (default: <code>admin</code>/<code>admin</code> eller inget lösenord)</li><li>Navigera till <strong>Network settings</strong> → <strong>Device name</strong></li><li>Ange device name manuellt</li></ol><h2 id="steg-7-kompilera-och-ladda-ner" tabindex="-1">Steg 7: Kompilera och ladda ner <a class="header-anchor" href="#steg-7-kompilera-och-ladda-ner" aria-label="Permalink to &quot;Steg 7: Kompilera och ladda ner&quot;">​</a></h2><h3 id="kompilera-hardvarekonfiguration" tabindex="-1">Kompilera hårdvarekonfiguration <a class="header-anchor" href="#kompilera-hardvarekonfiguration" aria-label="Permalink to &quot;Kompilera hårdvarekonfiguration&quot;">​</a></h3><ol><li>Högerklicka på PLC i projektträdet</li><li><strong>Compile</strong> → <strong>Hardware (rebuild all)</strong></li><li>Kontrollera att inga fel uppstår</li><li>Särskilt viktigt att Profinet-konfigurationen är korrekt</li></ol><h3 id="ladda-ner-till-plc" tabindex="-1">Ladda ner till PLC <a class="header-anchor" href="#ladda-ner-till-plc" aria-label="Permalink to &quot;Ladda ner till PLC&quot;">​</a></h3><ol><li>Anslut PC till PLC via Ethernet</li><li><strong>Online</strong> → <strong>Download to device</strong></li><li>Ladda ner: <ul><li>☑ Hardware configuration</li><li>☑ PLC program (om du redan programmerat styrning)</li></ul></li><li>PLC startar om och etablerar Profinet-kommunikation</li></ol><h2 id="steg-8-verifiera-profinet-anslutning" tabindex="-1">Steg 8: Verifiera Profinet-anslutning <a class="header-anchor" href="#steg-8-verifiera-profinet-anslutning" aria-label="Permalink to &quot;Steg 8: Verifiera Profinet-anslutning&quot;">​</a></h2><h3 id="kontrollera-i-tia-portal" tabindex="-1">Kontrollera i TIA Portal <a class="header-anchor" href="#kontrollera-i-tia-portal" aria-label="Permalink to &quot;Kontrollera i TIA Portal&quot;">​</a></h3><ol><li>Gå <strong>Online</strong> med PLC</li><li>Öppna <strong>Device View</strong> → <strong>Online &amp; Diagnostics</strong></li><li>Expandera <strong>PROFINET interface</strong> → <strong>IO-devices</strong></li><li>Frekvensomriktaren ska visas som: <ul><li>✅ <strong>Grön</strong> = Kommunikation OK</li><li>⚠️ <strong>Gul</strong> = Konfigureringsfel</li><li>❌ <strong>Röd</strong> = Ingen kommunikation</li></ul></li></ol><h3 id="led-indikering-pa-frekvensomriktaren" tabindex="-1">LED-indikering på frekvensomriktaren <a class="header-anchor" href="#led-indikering-pa-frekvensomriktaren" aria-label="Permalink to &quot;LED-indikering på frekvensomriktaren&quot;">​</a></h3><table tabindex="0"><thead><tr><th>LED</th><th>Färg</th><th>Status</th></tr></thead><tbody><tr><td><strong>PN</strong></td><td>Grön</td><td>Profinet OK</td></tr><tr><td><strong>PN</strong></td><td>Gul blinkande</td><td>Väntar på konfiguration</td></tr><tr><td><strong>PN</strong></td><td>Röd</td><td>Kommunikationsfel</td></tr></tbody></table><h2 id="vanliga-problem-och-losningar" tabindex="-1">Vanliga problem och lösningar <a class="header-anchor" href="#vanliga-problem-och-losningar" aria-label="Permalink to &quot;Vanliga problem och lösningar&quot;">​</a></h2><p>❌ <strong>Problem:</strong> &quot;IO-device not accessible&quot; ✅ <strong>Lösningar:</strong></p><ul><li>Kontrollera att frekvensomriktaren är påslagen</li><li>Verifiera Ethernet-kabel (ska vara CAT5e eller bättre)</li><li>Kontrollera att IP-adresser är i samma subnet</li><li>Assign device name om det inte är gjort</li></ul><p>❌ <strong>Problem:</strong> &quot;Telegram configuration error&quot; ✅ <strong>Lösningar:</strong></p><ul><li>Kontrollera att rätt telegram är valt i både TIA och omriktare</li><li>Verifiera parameter P2009 (device number) i omriktaren</li></ul><p>❌ <strong>Problem:</strong> &quot;Device name conflict&quot; ✅ <strong>Lösningar:</strong></p><ul><li>Kontrollera att device name är unikt i nätverket</li><li>Reset omriktaren till fabriksinställningar och konfigurera om</li></ul><h2 id="nasta-steg" tabindex="-1">Nästa steg <a class="header-anchor" href="#nasta-steg" aria-label="Permalink to &quot;Nästa steg&quot;">​</a></h2><p>Nu när Profinet-kommunikationen fungerar kan du:</p><ol><li>Programmera PLC-kod för att styra omriktaren (se <a href="./../08-frekvensomriktare/start-stop.html">Start/stop via PLC</a>)</li><li>Skapa HMI-kontroller för hastighetsreglering</li><li>Implementera övervakningsfunktioner</li></ol><h2 id="resurser-och-dokumentation" tabindex="-1">Resurser och dokumentation <a class="header-anchor" href="#resurser-och-dokumentation" aria-label="Permalink to &quot;Resurser och dokumentation&quot;">​</a></h2><h3 id="officiell-dokumentation" tabindex="-1">Officiell dokumentation <a class="header-anchor" href="#officiell-dokumentation" aria-label="Permalink to &quot;Officiell dokumentation&quot;">​</a></h3><ul><li><a href="https://support.industry.siemens.com/cs/document/49948856" target="_blank" rel="noreferrer">PROFINET Configuration Manual</a> - Profinet guide</li><li><a href="https://support.industry.siemens.com/cs/document/109476700" target="_blank" rel="noreferrer">Sinamics G120 Manual</a> - G120 manual</li><li><a href="https://support.industry.siemens.com/cs/document/109749880" target="_blank" rel="noreferrer">Sinamics Startdrive Manual</a> - Startdrive guide</li></ul><h3 id="gsd-filer-och-firmware" tabindex="-1">GSD-filer och firmware <a class="header-anchor" href="#gsd-filer-och-firmware" aria-label="Permalink to &quot;GSD-filer och firmware&quot;">​</a></h3><ul><li><a href="https://support.industry.siemens.com/cs/ww/en/ps/13483/dl" target="_blank" rel="noreferrer">Sinamics GSD Files</a> - Nedladdningscenter</li></ul><h3 id="video-tutorials" tabindex="-1">Video-tutorials <a class="header-anchor" href="#video-tutorials" aria-label="Permalink to &quot;Video-tutorials&quot;">​</a></h3><ul><li>YouTube: &quot;TIA Portal PROFINET configuration&quot;</li><li>YouTube: &quot;Sinamics G120 TIA Portal setup&quot;</li><li>YouTube: &quot;TIA Portal drive commissioning&quot;</li></ul><div class="tip custom-block"><p class="custom-block-title">Tips för avancerade användare</p><p>Utforska <strong>PROFIdrive-profilen</strong> för avancerad motion control med positionering, hastighetsramper och synkronisering av flera axlar.</p></div>',80)])])}const k=r(n,[["render",l]]);export{h as __pageData,k as default};
